import base64,hashlib,pathlib,shutil
run=pathlib.Path('/hb/groups/cornejo_training/StrepA_project_revamped/interproscan_all_significant_20261003T043208Z_b2a74f5f')
old=run/'scripts/postprocess.py'
backup=run/'provenance/postprocess.initial.py'
assert not backup.exists()
shutil.copy2(old,backup)
new=run/'scripts/postprocess.updated.py'
with new.open('xb') as f: f.write(base64.b64decode(''))
new.replace(old)
assets=run/'runtime/pipeline/assets'
source=pathlib.Path('/home/RESEARCH_USER/.nextflow/assets/ebi-pf-team/interproscan6/assets')
shutil.copytree(source,assets)
with (run/'provenance/pipeline.sha256').open('a') as f:
 for p in sorted(assets.rglob('*')):
  if p.is_file():
   digest=hashlib.sha256(p.read_bytes()).hexdigest()
   assert digest==hashlib.sha256((source/p.relative_to(assets)).read_bytes()).hexdigest()
   f.write(digest+'  '+str(p.relative_to(run))+'\n')
with (run/'provenance/change_log.txt').open('a') as f:
 f.write('Before analysis startup: added untouched installed assets to software snapshot; strengthened postprocessing with independent XML ID/sequence verification; preserved initial postprocessor.\n')
print('Postprocessor XML verification and software assets saved.')
